__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float dist = chf("Distance", 0.2f);
        int keep_base = chb("Keep Base", true) > 0.5f ? 1 : 0;
        int tri_count = in_count / 3;
        int count = 0;
        for (int t = 0; t < tri_count; t++) {
            int i0 = (t * 3 + 0) * 3;
            int i1 = (t * 3 + 1) * 3;
            int i2 = (t * 3 + 2) * 3;
            float px[3] = {in_pos[i0], in_pos[i1], in_pos[i2]};
            float py[3] = {in_pos[i0 + 1], in_pos[i1 + 1], in_pos[i2 + 1]};
            float pz[3] = {in_pos[i0 + 2], in_pos[i1 + 2], in_pos[i2 + 2]};
            float cr[3] = {in_col[i0], in_col[i1], in_col[i2]};
            float cg[3] = {in_col[i0 + 1], in_col[i1 + 1], in_col[i2 + 1]};
            float cb[3] = {in_col[i0 + 2], in_col[i1 + 2], in_col[i2 + 2]};
            // Face normal from the winding (CCW front): extrusion direction.
            float ux = px[1] - px[0], uy = py[1] - py[0], uz = pz[1] - pz[0];
            float vx = px[2] - px[0], vy = py[2] - py[0], vz = pz[2] - pz[0];
            // Negated cross: the templates' triangles wind clockwise seen
            // from outside under this renderer's convention, so the plain
            // cross(B-A, C-A) points inward.
            float nx = uz * vy - uy * vz;
            float ny = ux * vz - uz * vx;
            float nz = uy * vx - ux * vy;
            float len = sqrt(nx * nx + ny * ny + nz * nz);
            if (len > 1e-8f) { nx /= len; ny /= len; nz /= len; }
            float ox = nx * dist, oy = ny * dist, oz = nz * dist;
            // Top face: the input triangle offset along its normal, same winding.
            for (int v = 0; v < 3; v++) {
                int idx = count++;
                if (idx < max_vertices) {
                    out_pos[idx * 3 + 0] = px[v] + ox;
                    out_pos[idx * 3 + 1] = py[v] + oy;
                    out_pos[idx * 3 + 2] = pz[v] + oz;
                    out_col[idx * 3 + 0] = cr[v];
                    out_col[idx * 3 + 1] = cg[v];
                    out_col[idx * 3 + 2] = cb[v];
                }
            }
            // Side walls: one quad per edge, wound so the outside faces out
            // (CCW front) for a CCW input triangle and positive distance.
            for (int e = 0; e < 3; e++) {
                int s0 = e;
                int s1 = (e + 1) % 3;
                float wx[6] = {px[s0], px[s1], px[s1] + ox, px[s0], px[s1] + ox, px[s0] + ox};
                float wy[6] = {py[s0], py[s1], py[s1] + oy, py[s0], py[s1] + oy, py[s0] + oy};
                float wz[6] = {pz[s0], pz[s1], pz[s1] + oz, pz[s0], pz[s1] + oz, pz[s0] + oz};
                int wc[6] = {s0, s1, s1, s0, s1, s0};
                for (int v = 0; v < 6; v++) {
                    int idx = count++;
                    if (idx < max_vertices) {
                        out_pos[idx * 3 + 0] = wx[v];
                        out_pos[idx * 3 + 1] = wy[v];
                        out_pos[idx * 3 + 2] = wz[v];
                        out_col[idx * 3 + 0] = cr[wc[v]] * 0.85f;
                        out_col[idx * 3 + 1] = cg[wc[v]] * 0.85f;
                        out_col[idx * 3 + 2] = cb[wc[v]] * 0.85f;
                    }
                }
            }
            // Base: the original triangle, winding reversed so it faces away
            // from the extrusion.
            if (keep_base) {
                int ord[3] = {0, 2, 1};
                for (int v = 0; v < 3; v++) {
                    int s = ord[v];
                    int idx = count++;
                    if (idx < max_vertices) {
                        out_pos[idx * 3 + 0] = px[s];
                        out_pos[idx * 3 + 1] = py[s];
                        out_pos[idx * 3 + 2] = pz[s];
                        out_col[idx * 3 + 0] = cr[s];
                        out_col[idx * 3 + 1] = cg[s];
                        out_col[idx * 3 + 2] = cb[s];
                    }
                }
            }
        }
        *out_count = count > max_vertices ? max_vertices : count;
    }
}
